func (s *Store) upsertEstimatesTx(tx *sql.Tx, id string, obj map[string]any, data json.RawMessage) error {
	if _, err := tx.Exec(
		`INSERT INTO "estimates" ("id", "zoho_finance_id", "data", "synced_at")
		 VALUES (?, ?, ?, ?)
		 ON CONFLICT("id") DO UPDATE SET "zoho_finance_id" = excluded."zoho_finance_id", "data" = excluded."data", "synced_at" = excluded."synced_at"`,
		id,
		lookupFieldValue(obj, "zoho_finance_id"),
		string(data),
		time.Now(),
	); err != nil {
		return fmt.Errorf("insert into estimates: %w", err)
	}

	return nil
}

